'use client'

import { HttpLink } from '@apollo/client'
import { ApolloClient, ApolloNextAppProvider, InMemoryCache } from '@apollo/client-integration-nextjs'
import type { ReactElement, ReactNode } from 'react'

function makeClient(): ApolloClient {
  return new ApolloClient({
    cache: new InMemoryCache(),
    link: new HttpLink({ uri: '/api/graphql' }),
  })
}

export function InventoryApolloProvider({ children }: { children: ReactNode }): ReactElement {
  return <ApolloNextAppProvider makeClient={makeClient}>{children}</ApolloNextAppProvider>
}

fragment ImportJobSummary on ImportJob {
  jobId
  status
  forceOverwrite
  uploadExpiresAt
  finishedAt
  rowsRead
  rowsApplied
  rowsUnchanged
  rowsRejected
  failureCode
}

mutation CreateImport($force: Boolean!) {
  createImportJob(mode: DELTA, forceOverwrite: $force) {
    job {
      ...ImportJobSummary
    }
    uploadUrl
    uploadHeaders {
      name
      value
    }
  }
}

query ImportStatus($id: ID!) {
  importJob(jobId: $id) {
    ...ImportJobSummary
  }
}

query RowErrors($id: ID!, $page: Int!) {
  importRowErrors(jobId: $id, page: $page, size: 25) {
    items {
      rowNumber
      code
      frameId
      detail
    }
    page
    hasNext
  }
}

query Frames($page: Int!) {
  frames(page: $page, size: 25) {
    page
    size
    hasNext
    items {
      frameId
      attributes {
        status
        environment
        siteNo
        address
        location {
          town
          postcode
        }
        format {
          technology
          formatCode
        }
      }
    }
  }
}

query FrameHistory($id: ID!) {
  frameHistory(frameId: $id) {
    versionId
    validFrom
    validTo
    current
    changeSource
    closedByChangeSource
    importJobId
    attributes {
      status
      statusReason
    }
  }
}

