        </section>
        <section hidden={area !== 'imports'}>
          <div className="page-heading">
            <div>
              <h1>Imports</h1>
              <p className="subtle">Upload inventory CSV files and review import results.</p>
            </div>
          </div>
          <InventoryImport trackedId={jobId} onTrack={setJobId} />
        </section>
      </main>
    </>
  )
}
